function csvValue(v:unknown){let s=String(v??'');if(/^[=+@\t\r]|^-[^\d]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function download(name:string,text:string,type='text/csv'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportTrades(es:Entry[]){const headers=['Date','Title','Symbol','Side','Entry time','Exit time','Entry price','Exit price','Lots','Stop','Fees','Net P&L','R multiple','Setup','Outcome','Tags','Reviewed'];const rows=es.map(e=>[e.date,e.title,e.symbol,e.side,e.execution.entryTime,e.execution.exitTime,e.execution.entry,e.execution.exit,e.execution.size,e.execution.stop,e.execution.fees,e.netPnl,e.rMultiple,e.setup,e.outcome,e.tags.join('|'),!!e.execution.reviewed]);download('trades.csv',[headers,...rows].map(r=>r.map(csvValue).join(',')).join('\r\n'))}
function Metric({label,value,detail}:{label:string;value:string;detail?:string}){return <div className="metric"><span>{label}</span><strong>{value}</strong>{detail&&<small>{detail}</small>}</div>}
