 const[trade,setTrade]=useState<Entry|null>(null),[accountDraft,setAccountDraft]=useState<Account|null>(null),[docDraft,setDocDraft]=useState<{kind:'playbook'|'note'|'goal';data:Playbook|JournalNote|Goal}|null>(null),[selected,setSelected]=useState<string[]>([]),[sort,setSort]=useState('date'),[ascending,setAscending]=useState(false),[columns,setColumns]=useState(['Symbol','Side','Result','R','Setup','Reviewed']),[columnOpen,setColumnOpen]=useState(false),[month,setMonth]=useState(today().slice(0,7)),[selectedDay,setSelectedDay]=useState(''),[yearView,setYearView]=useState(false),[report,setReport]=useState('Overview'),[ask,setAsk]=useState(''),[answer,setAnswer]=useState(''),[widgets,setWidgets]=useState(['equity','calendar','recent','outcomes']),[widgetSettings,setWidgetSettings]=useState(false);
