 async function load(){setError('');try{const results=await Promise.all(['/api/entries','/api/accounts','/api/documents'].map(async url=>{const r=await fetch(url);const d=await r.json() as {error?:string;entries?:Entry[];accounts?:Account[];documents?:DocumentRecord[]};if(!r.ok)throw new Error(d.error);return d}));setEntries(results[0].entries||[]);setAccounts(results[1].accounts||[]);setDocuments(results[2].documents||[])}catch(e){setError(e instanceof Error?e.message:'Could not load your journal.')}finally{setLoading(false)}}
 useEffect(()=>{void load();const stored=localStorage.getItem('kacey-theme');const next=stored==='light'||stored==='dark'?stored:matchMedia('(prefers-color-scheme: light)').matches?'light':'dark';setTheme(next);document.documentElement.dataset.theme=next;const size=localStorage.getItem('kacey-text-size')||'1';if(['1','1.125','1.25'].includes(size)){setTextSize(size);document.documentElement.style.setProperty('--text-scale',size)}setShortcuts(localStorage.getItem('kacey-shortcuts')==='true');const system=matchMedia('(prefers-color-scheme: light)');const sync=()=>{if(!localStorage.getItem('kacey-theme')){const value=system.matches?'light':'dark';setTheme(value);document.documentElement.dataset.theme=value}};system.addEventListener('change',sync);try{const w=JSON.parse(localStorage.getItem('kacey-widgets')||'null');if(Array.isArray(w))setWidgets(w)}catch{}return()=>system.removeEventListener('change',sync)},[]);
 function add(kind:'Trade'|'Idea'='Trade',date=today(prefs.timezone)){const e=blank(kind,date);e.accountId=accountFilter!=='all'&&accountFilter!=='unassigned'?accountFilter:prefs.defaultAccount||null;const a=accounts.find(a=>a.id===e.accountId);if(a?.startingBalance!==null&&a?.startingBalance!==undefined)e.riskAmount=Math.round((a.startingBalance+stats(entries.filter(x=>x.accountId===a.id),'money').total)*prefs.defaultRisk)/100;setTrade(e)}
 useEffect(()=>{const key=(e:KeyboardEvent)=>{if(!shortcuts)return;const target=e.target as HTMLElement;if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(target.tagName)&&!trade&&!accountDraft&&!docDraft){e.preventDefault();add()}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)});
 function navigate(v:string){setView(v);setSelected([]);queueMicrotask(()=>document.getElementById('page-title')?.focus())}
