 const currencySet=new Set(scoped.filter(e=>e.netPnl!==null).map(e=>e.execution.currency||accounts.find(a=>a.id===e.accountId)?.currency||'Unknown'));const pickedAccount=accounts.find(a=>a.id===accountFilter);const canMoney=!!pickedAccount||currencySet.size===1&&!currencySet.has('Unknown');const currency=pickedAccount?.currency||[...currencySet][0]||prefs.currency;const displayMode=canMoney?mode:'r';const s=stats(scoped,displayMode);const days=daily(scoped,displayMode);const closed=closedTrades(scoped);const tradingHealth=closed.length?Math.round(s.winRate*.2+Math.min(100,Math.max(0,(stats(scoped).expectancy+1)*40))*.3+s.adherence*.35+(100-closed.filter(e=>e.fomo).length/closed.length*100)*.15):null;
 const sorted=[...scoped.filter(e=>e.kind===(view==='ideas'?'Idea':'Trade'))].sort((a,b)=>{let av:unknown=(a as unknown as Record<string,unknown>)[sort],bv:unknown=(b as unknown as Record<string,unknown>)[sort];if(sort==='reviewed'){av=!!a.execution.reviewed;bv=!!b.execution.reviewed}const v=typeof av==='number'&&typeof bv==='number'?av-bv:String(av??'').localeCompare(String(bv??''));return ascending?v:-v});
 function reset(){setAccountFilter('all');setStart('');setEnd('');setQuery('');setSetup('all');setTag('');setOutcome('all');setSide('all');setEmotion('all');setReviewed('all');setGrade('all');setRMin('');setRMax('')}
 async function saveEntry(e:Entry){const fd=new FormData();fd.set('entry',JSON.stringify(e));const r=await fetch('/api/entries',{method:e.id?'PUT':'POST',body:fd});const data=await r.json() as {error?:string};if(!r.ok)throw new Error(data.error)}
 async function deleteEntry(e:Entry){if(!await confirmAction({name:e.title,consequence:'Delete this entry and its screenshots permanently.'}))return;try{const r=await fetch('/api/entries?id='+e.id,{method:'DELETE'}),d=await r.json() as {error?:string};if(!r.ok)throw new Error(d.error);setTrade(null);toast.success('Entry deleted');await load()}catch(e){toast.error(e instanceof Error?e.message:'Could not delete.')}}
