 async function bulk(action:string){const rows=entries.filter(e=>e.id&&selected.includes(e.id));if(!rows.length)return;let label='',to:string|null=null;if(action==='tag'){label=bulkTag.trim();if(!label){toast.error('Enter a tag to add.');return}}if(action==='account'){to=bulkAccount||null}if(action==='account'&&to&&rows.some(e=>{const from=e.execution.currency||accounts.find(a=>a.id===e.accountId)?.currency;return from&&from!==accounts.find(a=>a.id===to)?.currency})){toast.error('Move trades between different currencies individually and recalculate their P&L.');return}if(action==='delete'&&!await confirmAction({name:`${rows.length} selected entries`,consequence:'Permanently delete the selected entries and their screenshots.'}))return;try{for(const e of rows){if(action==='delete'){const r=await fetch('/api/entries?id='+e.id,{method:'DELETE'});if(!r.ok)throw new Error('Some entries could not be deleted.')}else{const next=action==='tag'?{...e,tags:Array.from(new Set([...e.tags,label]))}:action==='review'?{...e,execution:{...e.execution,reviewed:true}}:{...e,accountId:to,execution:{...e.execution,calc:false}};await saveEntry(next)}}setSelected([]);toast.success('Selected entries updated');await load()}catch(e){toast.error(e instanceof Error?e.message:'Could not update all entries.');await load()}}
